package services

import (
 "testing"
 "time"
 "fluxo/models"
)
func editorialFixture()(models.Tarefa,models.Usuario){return models.Tarefa{Titulo:"Vídeo da campanha",Descricao:"Roteiro aprovado na pauta",TipoConteudo:"video",Etapa:"pauta",Canal:"YouTube",SetorID:"ascom",Prazo:time.Now().Add(72*time.Hour)},models.Usuario{ID:"gestor",Perfil:"gestor",SetorID:"ascom"}}
func advance(t *testing.T,previous models.Tarefa,stage string,u models.Usuario)models.Tarefa{t.Helper();request:=previous;request.Etapa=stage;request.Anotacao="Avanço editorial";if stage=="publicado"{request.LinkPublicado="https://example.com/video"};result,err:=ApplyEditorial(&previous,request,u,time.Now());if err!=nil{t.Fatal(err)};return result}
func TestEditorialPublicationRequiresReviewAndApproval(t *testing.T){request,u:=editorialFixture();current,err:=ApplyEditorial(nil,request,u,time.Now());if err!=nil{t.Fatal(err)};current=advance(t,current,"producao",u);skip:=current;skip.Etapa="revisao";if _,err=ApplyEditorial(&current,skip,u,time.Now());err==nil{t.Fatal("video must pass editing")};current=advance(t,current,"edicao",u);current=advance(t,current,"revisao",u);current=advance(t,current,"aprovacao",u);server:=u;server.Perfil="servidor";approve:=current;approve.Etapa="pronto_publicacao";if _,err=ApplyEditorial(&current,approve,server,time.Now());err==nil{t.Fatal("server cannot approve")};outsider:=u;outsider.SetorID="outro";if _,err=ApplyEditorial(&current,approve,outsider,time.Now());err==nil{t.Fatal("manager from another sector cannot approve")};current=advance(t,current,"pronto_publicacao",u);if current.AprovadoEm==nil||current.AprovadorID==nil{t.Fatal("approval metadata missing")};missing:=current;missing.Etapa="publicado";if _,err=ApplyEditorial(&current,missing,u,time.Now());err==nil{t.Fatal("publication link required")};current=advance(t,current,"publicado",u);if current.Status!="concluida"||current.ConcluidoEm==nil||current.PublicadoEm==nil{t.Fatal("publication must finish delivery")}}
func TestEditorialEditsInvalidateApproval(t *testing.T){request,u:=editorialFixture();current,_:=ApplyEditorial(nil,request,u,time.Now());for _,stage:=range []string{"producao","edicao","revisao","aprovacao","pronto_publicacao"}{current=advance(t,current,stage,u)};modified:=current;modified.LinkMaterial="https://example.com/version-2";updated,err:=ApplyEditorial(&current,modified,u,time.Now());if err!=nil{t.Fatal(err)};if updated.Etapa!="revisao"||updated.AprovadoEm!=nil||updated.AprovadorID!=nil{t.Fatal("changed material needs new signoff")};stale:=updated;stale.Versao=current.Versao;if _,err=ApplyEditorial(&updated,stale,u,time.Now());err==nil{t.Fatal("stale writes must be rejected")}}
func TestEditorialScheduleAndReadOnlyMetadata(t *testing.T){request,u:=editorialFixture();pastDeadline:=request.Prazo.Add(time.Hour);request.PrazoEtapa=&pastDeadline;if _,err:=ApplyEditorial(nil,request,u,time.Now());err==nil{t.Fatal("stage deadline cannot exceed delivery")};request.PrazoEtapa=nil;forged:=time.Now();request.AprovadoEm=&forged;request.AprovadorID=&u.ID;result,err:=ApplyEditorial(nil,request,u,time.Now());if err!=nil{t.Fatal(err)};if result.AprovadoEm!=nil||result.AprovadorID!=nil{t.Fatal("client cannot forge signoff")}}
